-- Phase 2.2C: provider-independent, owner-local IOC candidate intake.
begin;
alter type public.indicator_type add value if not exists 'CIDR' after 'IP';
commit;

begin;
create type public.ioc_candidate_type as enum ('IPV4','IPV6','CIDR','DOMAIN','HOSTNAME','URL','MD5','SHA1','SHA256','CVE');
create type public.ioc_candidate_status as enum ('NEW','REVIEWED','ACCEPTED','DISMISSED','EXPIRED');
create type public.ioc_ingestion_trigger as enum ('MANUAL','SCHEDULED','TEST');
create type public.ioc_ingestion_run_status as enum ('RUNNING','SUCCEEDED','NOT_MODIFIED','FAILED');
create type public.ioc_connection_health as enum ('UNKNOWN','HEALTHY','DEGRADED','FAILED');

create table public.ioc_provider_connections(
 id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,provider_key text not null check(provider_key~'^[A-Z][A-Z0-9_]{2,63}$'),display_name text not null check(char_length(display_name) between 1 and 200),enabled boolean not null default true,scheduler_enabled boolean not null default false,sync_interval_minutes integer not null default 60 check(sync_interval_minutes between 15 and 10080),next_scheduled_sync_at timestamptz,last_scheduled_sync_at timestamptz,last_checked_at timestamptz,last_success_at timestamptz,health_status public.ioc_connection_health not null default 'UNKNOWN',consecutive_failures integer not null default 0 check(consecutive_failures>=0),last_error_code text check(char_length(last_error_code)<=100),last_error_message text check(char_length(last_error_message)<=500),lease_token_hash text check(lease_token_hash~'^[0-9a-f]{64}$'),lease_run_id uuid,lease_expires_at timestamptz,created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),archived_at timestamptz,unique(owner_id,provider_key),unique(owner_id,id),check(owner_id=created_by));
create table public.ioc_ingestion_runs(id uuid primary key default gen_random_uuid(),owner_id uuid not null,provider_connection_id uuid not null,provider_key text not null,trigger_type public.ioc_ingestion_trigger not null,status public.ioc_ingestion_run_status not null default 'RUNNING',started_at timestamptz not null default now(),completed_at timestamptz,lease_token_hash text not null check(lease_token_hash~'^[0-9a-f]{64}$'),lease_expires_at timestamptz not null,starting_cursor_version bigint,starting_cursor_hash text,candidate_count integer not null default 0,source_observation_count integer not null default 0,created_count integer not null default 0,updated_count integer not null default 0,skipped_count integer not null default 0,deduplicated_count integer not null default 0,error_code text check(char_length(error_code)<=100),error_message text check(char_length(error_message)<=500),created_at timestamptz not null default now(),unique(owner_id,id),foreign key(owner_id,provider_connection_id) references public.ioc_provider_connections(owner_id,id) on delete restrict);
alter table public.ioc_provider_connections add foreign key(owner_id,lease_run_id) references public.ioc_ingestion_runs(owner_id,id) on delete restrict;
create table public.ioc_candidates(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,candidate_type public.ioc_candidate_type not null,normalized_value text not null check(char_length(normalized_value) between 1 and 8000),network_port integer,status public.ioc_candidate_status not null default 'NEW',first_seen_at timestamptz,last_seen_at timestamptz,first_ingested_at timestamptz not null default now(),last_ingested_at timestamptz not null default now(),highest_confidence integer check(highest_confidence between 0 and 100),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),port_identity integer generated always as(coalesce(network_port,0)) stored,unique(owner_id,id),unique(owner_id,candidate_type,normalized_value,port_identity),check((candidate_type in('IPV4','IPV6') and(network_port is null or network_port between 1 and 65535))or(candidate_type not in('IPV4','IPV6')and network_port is null)),check(first_seen_at is null or last_seen_at is null or last_seen_at>=first_seen_at));
create table public.ioc_candidate_sources(id uuid primary key default gen_random_uuid(),owner_id uuid not null,candidate_id uuid not null,provider_connection_id uuid not null,ingestion_run_id uuid not null,provider_item_id text not null check(char_length(provider_item_id) between 1 and 500),source_fingerprint text not null check(source_fingerprint~'^[0-9a-f]{64}$'),original_value text not null check(char_length(original_value) between 1 and 8000),provider_reference_url text check(char_length(provider_reference_url)<=4096 and provider_reference_url~'^https?://'),threat_type text check(char_length(threat_type)<=500),malware_family text check(char_length(malware_family)<=500),confidence_score integer check(confidence_score between 0 and 100),provider_first_seen timestamptz,provider_last_seen timestamptz,first_observed_at timestamptz not null default now(),last_observed_at timestamptz not null default now(),observation_count integer not null default 1 check(observation_count>0),tags text[] not null default '{}',metadata jsonb not null default '{}' check(jsonb_typeof(metadata)='object' and pg_column_size(metadata)<=32768),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,id),unique(owner_id,provider_connection_id,source_fingerprint),foreign key(owner_id,candidate_id) references public.ioc_candidates(owner_id,id) on delete restrict,foreign key(owner_id,provider_connection_id) references public.ioc_provider_connections(owner_id,id) on delete restrict,foreign key(owner_id,ingestion_run_id) references public.ioc_ingestion_runs(owner_id,id) on delete restrict,check(cardinality(tags)<=50));
create table public.ioc_provider_cursors(id uuid primary key default gen_random_uuid(),owner_id uuid not null,provider_connection_id uuid not null,cursor_value text not null check(char_length(cursor_value)<=8000),cursor_version bigint not null default 1 check(cursor_version>0),cursor_hash text not null check(cursor_hash~'^[0-9a-f]{64}$'),updated_at timestamptz not null default now(),unique(owner_id,provider_connection_id),foreign key(owner_id,provider_connection_id) references public.ioc_provider_connections(owner_id,id) on delete cascade);
create table public.ioc_candidate_acceptances(id uuid primary key default gen_random_uuid(),owner_id uuid not null,candidate_id uuid not null,project_id uuid not null,indicator_id uuid,cve_id uuid,accepted_by uuid not null references auth.users(id) on delete restrict,analyst_note text not null default '' check(char_length(analyst_note)<=5000),accepted_at timestamptz not null default now(),candidate_type public.ioc_candidate_type not null,provider_labels text[] not null default '{}',unique(owner_id,candidate_id,project_id),foreign key(owner_id,candidate_id) references public.ioc_candidates(owner_id,id) on delete restrict,foreign key(project_id,indicator_id) references public.indicators(project_id,id) on delete restrict,foreign key(project_id,cve_id) references public.cves(project_id,id) on delete restrict,check((indicator_id is null)<>(cve_id is null)),check(owner_id=accepted_by));
create index ioc_candidates_inbox_idx on public.ioc_candidates(owner_id,last_seen_at desc nulls last,id desc);create index ioc_sources_candidate_idx on public.ioc_candidate_sources(owner_id,candidate_id,last_observed_at desc,id desc);create index ioc_runs_connection_idx on public.ioc_ingestion_runs(owner_id,provider_connection_id,started_at desc);

create function public.triage_ioc_candidate(p_candidate_id uuid,p_action text) returns public.ioc_candidates language plpgsql security definer set search_path='' as $$declare c public.ioc_candidates;begin select * into c from public.ioc_candidates where id=p_candidate_id and owner_id=auth.uid() for update;if c.id is null then raise exception 'CANDIDATE_NOT_FOUND';end if;if p_action='REVIEW'and c.status='NEW'then c.status='REVIEWED';elsif p_action='DISMISS'and c.status in('NEW','REVIEWED')then c.status='DISMISSED';elsif p_action='RESTORE'and c.status='DISMISSED'then c.status='NEW';else raise exception 'INVALID_STATUS_TRANSITION';end if;update public.ioc_candidates set status=c.status,updated_at=now()where id=c.id returning * into c;return c;end$$;
create function public.claim_ioc_connection(p_owner_id uuid,p_connection_id uuid,p_trigger public.ioc_ingestion_trigger) returns table(owner_id uuid,connection_id uuid,run_id uuid,lease_token uuid,provider_key text,cursor_value text,cursor_version bigint) language plpgsql security definer set search_path='' as $$declare c public.ioc_provider_connections;t uuid:=gen_random_uuid();r uuid:=gen_random_uuid();v bigint;cur text;begin select * into c from public.ioc_provider_connections pc where pc.id=p_connection_id and pc.owner_id=p_owner_id for update;if c.id is null then raise exception 'CONNECTION_UNAVAILABLE';end if;if not c.enabled or c.archived_at is not null then raise exception 'PROVIDER_DISABLED';end if;if c.lease_expires_at>now()then raise exception 'SYNC_ALREADY_RUNNING';end if;select x.cursor_version,x.cursor_value into v,cur from public.ioc_provider_cursors x where x.owner_id=p_owner_id and x.provider_connection_id=p_connection_id;insert into public.ioc_ingestion_runs(id,owner_id,provider_connection_id,provider_key,trigger_type,lease_token_hash,lease_expires_at,starting_cursor_version,starting_cursor_hash)values(r,p_owner_id,p_connection_id,c.provider_key,p_trigger,encode(public.digest(t::text,'sha256'),'hex'),now()+interval'5 minutes',v,case when cur is null then null else encode(public.digest(cur,'sha256'),'hex')end);update public.ioc_provider_connections set lease_token_hash=encode(public.digest(t::text,'sha256'),'hex'),lease_run_id=r,lease_expires_at=now()+interval'5 minutes',updated_at=now()where id=c.id;return query select p_owner_id,p_connection_id,r,t,c.provider_key,cur,v;end$$;
create function public.complete_ioc_ingestion(p_owner_id uuid,p_connection_id uuid,p_run_id uuid,p_lease_token uuid,p_status public.ioc_ingestion_run_status,p_starting_cursor_version bigint,p_next_cursor text,p_items jsonb) returns public.ioc_ingestion_runs language plpgsql security definer set search_path='' as $$declare c public.ioc_provider_connections;r public.ioc_ingestion_runs;j jsonb;candidate uuid;created_n int:=0;updated_n int:=0;skip_n int:=0;source_n int:=0;ts timestamptz:=clock_timestamp();tags text[];was_created boolean;begin if p_status not in('SUCCEEDED','NOT_MODIFIED')or jsonb_typeof(p_items)<>'array'or jsonb_array_length(p_items)>1000 or pg_column_size(p_items)>10485760 or(p_status='NOT_MODIFIED'and jsonb_array_length(p_items)>0)then raise exception 'INVALID_CANDIDATE_PAYLOAD';end if;select * into c from public.ioc_provider_connections where owner_id=p_owner_id and id=p_connection_id for update;select * into r from public.ioc_ingestion_runs where owner_id=p_owner_id and id=p_run_id and provider_connection_id=p_connection_id for update;if c.id is null or r.id is null or not c.enabled or c.archived_at is not null or r.status<>'RUNNING'or c.lease_run_id<>p_run_id or c.lease_token_hash<>encode(public.digest(p_lease_token::text,'sha256'),'hex')or r.lease_token_hash<>c.lease_token_hash or c.lease_expires_at<=ts or r.lease_expires_at<=ts or r.starting_cursor_version is distinct from p_starting_cursor_version then raise exception 'STALE_INGESTION_LEASE';end if;for j in select * from jsonb_array_elements(p_items)loop begin if(j->>'candidate_type')not in('IPV4','IPV6','CIDR','DOMAIN','HOSTNAME','URL','MD5','SHA1','SHA256','CVE')or char_length(j->>'normalized_value')not between 1 and 8000 or char_length(j->>'original_value')not between 1 and 8000 or char_length(j->>'provider_item_id')not between 1 and 500 or(j->>'source_fingerprint')!~'^[0-9a-f]{64}$' or jsonb_typeof(coalesce(j->'metadata','{}'))<>'object'or pg_column_size(coalesce(j->'metadata','{}'))>32768 or jsonb_typeof(coalesce(j->'tags','[]'))<>'array'or jsonb_array_length(coalesce(j->'tags','[]'))>50 then raise exception 'skip';end if;tags:=array(select x from jsonb_array_elements_text(coalesce(j->'tags','[]'))x);if exists(select 1 from unnest(tags)x where char_length(x)>100)then raise exception 'skip';end if;insert into public.ioc_candidates(owner_id,candidate_type,normalized_value,network_port,first_seen_at,last_seen_at,highest_confidence)values(p_owner_id,(j->>'candidate_type')::public.ioc_candidate_type,j->>'normalized_value',nullif(j->>'network_port','')::int,nullif(j->>'first_seen_at','')::timestamptz,nullif(j->>'last_seen_at','')::timestamptz,nullif(j->>'confidence_score','')::int)on conflict(owner_id,candidate_type,normalized_value,port_identity)do update set last_seen_at=greatest(public.ioc_candidates.last_seen_at,excluded.last_seen_at),last_ingested_at=ts,highest_confidence=greatest(public.ioc_candidates.highest_confidence,excluded.highest_confidence),updated_at=ts returning id,(xmax=0)into candidate,was_created;if was_created then created_n:=created_n+1;else updated_n:=updated_n+1;end if;insert into public.ioc_candidate_sources(owner_id,candidate_id,provider_connection_id,ingestion_run_id,provider_item_id,source_fingerprint,original_value,provider_reference_url,threat_type,malware_family,confidence_score,provider_first_seen,provider_last_seen,tags,metadata)values(p_owner_id,candidate,p_connection_id,p_run_id,j->>'provider_item_id',j->>'source_fingerprint',j->>'original_value',j->>'provider_reference_url',j->>'threat_type',j->>'malware_family',nullif(j->>'confidence_score','')::int,nullif(j->>'first_seen_at','')::timestamptz,nullif(j->>'last_seen_at','')::timestamptz,tags,coalesce(j->'metadata','{}'))on conflict(owner_id,provider_connection_id,source_fingerprint)do update set ingestion_run_id=p_run_id,last_observed_at=ts,observation_count=public.ioc_candidate_sources.observation_count+1,updated_at=ts;source_n:=source_n+1;exception when others then skip_n:=skip_n+1;end;end loop;if p_next_cursor is not null then if char_length(p_next_cursor)>8000 then raise exception 'CURSOR_MISMATCH';end if;insert into public.ioc_provider_cursors(owner_id,provider_connection_id,cursor_value,cursor_version,cursor_hash)values(p_owner_id,p_connection_id,p_next_cursor,coalesce(p_starting_cursor_version,0)+1,encode(public.digest(p_next_cursor,'sha256'),'hex'))on conflict(owner_id,provider_connection_id)do update set cursor_value=excluded.cursor_value,cursor_version=excluded.cursor_version,cursor_hash=excluded.cursor_hash,updated_at=ts;end if;update public.ioc_ingestion_runs set status=p_status,completed_at=ts,candidate_count=created_n+updated_n,source_observation_count=source_n,created_count=created_n,updated_count=updated_n,skipped_count=skip_n where id=p_run_id returning * into r;update public.ioc_provider_connections set lease_token_hash=null,lease_run_id=null,lease_expires_at=null,last_checked_at=ts,last_success_at=ts,health_status='HEALTHY',consecutive_failures=0,last_error_code=null,last_error_message=null,next_scheduled_sync_at=case when scheduler_enabled then ts+make_interval(mins=>sync_interval_minutes)end,updated_at=ts where id=p_connection_id and lease_run_id=p_run_id;return r;end$$;
create function public.fail_ioc_ingestion(p_owner_id uuid,p_connection_id uuid,p_run_id uuid,p_lease_token uuid,p_error_code text,p_error_message text)returns public.ioc_ingestion_runs language plpgsql security definer set search_path='' as $$declare r public.ioc_ingestion_runs;begin update public.ioc_ingestion_runs set status='FAILED',completed_at=now(),error_code=left(p_error_code,100),error_message=left(p_error_message,500)where id=p_run_id and owner_id=p_owner_id and provider_connection_id=p_connection_id and status='RUNNING'and lease_token_hash=encode(public.digest(p_lease_token::text,'sha256'),'hex')returning * into r;if r.id is null then raise exception 'STALE_INGESTION_LEASE';end if;update public.ioc_provider_connections set lease_token_hash=null,lease_run_id=null,lease_expires_at=null,health_status='FAILED',consecutive_failures=consecutive_failures+1,last_error_code=r.error_code,last_error_message=r.error_message,updated_at=now()where id=p_connection_id and owner_id=p_owner_id and lease_run_id=p_run_id and lease_token_hash=r.lease_token_hash;if not found then raise exception 'STALE_INGESTION_LEASE';end if;return r;end$$;
create function public.accept_ioc_candidate(p_candidate_id uuid,p_project_id uuid,p_note text,p_cve_severity public.cve_severity default null)returns jsonb language plpgsql security definer set search_path='' as $$declare c public.ioc_candidates;a public.ioc_candidate_acceptances;i uuid;v_cve uuid;created boolean:=false;itype public.indicator_type;observed text;labels text[];begin if auth.uid()is null or not exists(select 1 from public.projects where id=p_project_id and owner_id=auth.uid())then raise exception 'INVESTIGATION_NOT_FOUND';end if;if char_length(coalesce(p_note,''))>5000 then raise exception 'ACCEPTANCE_CONFLICT';end if;select * into c from public.ioc_candidates where id=p_candidate_id and owner_id=auth.uid()for update;if c.id is null then raise exception 'CANDIDATE_NOT_FOUND';end if;select array_agg(distinct pc.display_name order by pc.display_name),min(s.original_value)into labels,observed from public.ioc_candidate_sources s join public.ioc_provider_connections pc on pc.id=s.provider_connection_id where s.owner_id=c.owner_id and s.candidate_id=c.id;if c.candidate_type='CVE'then if p_cve_severity is null then raise exception 'ACCEPTANCE_CONFLICT';end if;insert into public.cves(project_id,cve_id,severity,description)values(p_project_id,c.normalized_value,p_cve_severity,'')on conflict(project_id,cve_id)do nothing returning id into v_cve;if v_cve is null then select id into v_cve from public.cves where project_id=p_project_id and cve_id=c.normalized_value;else created:=true;end if;else itype:=case when c.candidate_type in('IPV4','IPV6')then'IP'::public.indicator_type when c.candidate_type='CIDR'then'CIDR'::public.indicator_type when c.candidate_type in('DOMAIN','HOSTNAME')then'DOMAIN'::public.indicator_type when c.candidate_type='URL'then'URL'::public.indicator_type else'HASH'::public.indicator_type end;insert into public.indicators(project_id,value,type,confidence,source,tags,first_seen,status)values(p_project_id,c.normalized_value,itype,'MEDIUM',array_to_string(labels,', '),case when c.candidate_type in('MD5','SHA1','SHA256')then array[c.candidate_type::text,'IOC_INBOX']else array['IOC_INBOX']end,c.first_seen_at,'UNVERIFIED')on conflict(project_id,type,normalized_value)do nothing returning id into i;if i is null then select id into i from public.indicators where project_id=p_project_id and type=itype and normalized_value=public.normalize_indicator_value(c.normalized_value,itype);else created:=true;end if;insert into public.indicator_observations(project_id,indicator_id,observed_value,observed_at,origin_kind,source_label,analyst_note,confidence,created_by)values(p_project_id,i,coalesce(observed,c.normalized_value)||case when c.network_port is null then''else':'||c.network_port end,c.last_seen_at,'IMPORT',left(array_to_string(labels,', '),500),coalesce(p_note,'')||case when c.network_port is null then''else E'\nNetwork port: '||c.network_port end,'MEDIUM',auth.uid());end if;insert into public.ioc_candidate_acceptances(owner_id,candidate_id,project_id,indicator_id,cve_id,accepted_by,analyst_note,candidate_type,provider_labels)values(c.owner_id,c.id,p_project_id,i,v_cve,auth.uid(),coalesce(p_note,''),c.candidate_type,coalesce(labels,'{}'))on conflict(owner_id,candidate_id,project_id)do update set analyst_note=public.ioc_candidate_acceptances.analyst_note returning * into a;update public.ioc_candidates set status='ACCEPTED',updated_at=now()where id=c.id;return jsonb_build_object('ok',true,'acceptance_id',a.id,'indicator_id',i,'cve_id',v_cve,'created',created);end$$;
create function public.list_ioc_inbox(p_status public.ioc_candidate_status default null,p_type public.ioc_candidate_type default null,p_provider uuid default null,p_search text default null,p_min_confidence integer default null,p_max_confidence integer default null,p_has_port boolean default null,p_project_id uuid default null,p_cursor_at timestamptz default null,p_cursor_id uuid default null,p_limit integer default 30)returns table(id uuid,candidate_type public.ioc_candidate_type,normalized_value text,network_port integer,status public.ioc_candidate_status,first_seen_at timestamptz,last_seen_at timestamptz,highest_confidence integer,provider_count bigint,source_count bigint,latest_provider text,threat_types text[],malware_families text[],tags text[],acceptance_count bigint)language sql security invoker set search_path='' as $$select c.id,c.candidate_type,c.normalized_value,c.network_port,c.status,c.first_seen_at,c.last_seen_at,c.highest_confidence,count(distinct s.provider_connection_id),count(s.id),(array_agg(pc.display_name order by s.last_observed_at desc))[1],array_remove(array_agg(distinct s.threat_type),null),array_remove(array_agg(distinct s.malware_family),null),coalesce((select array_agg(distinct x)from public.ioc_candidate_sources sx cross join unnest(sx.tags)x where sx.owner_id=c.owner_id and sx.candidate_id=c.id),'{}'),(select count(*)from public.ioc_candidate_acceptances a where a.owner_id=c.owner_id and a.candidate_id=c.id)from public.ioc_candidates c left join public.ioc_candidate_sources s on s.owner_id=c.owner_id and s.candidate_id=c.id left join public.ioc_provider_connections pc on pc.owner_id=s.owner_id and pc.id=s.provider_connection_id where c.owner_id=auth.uid()and(p_status is null or c.status=p_status)and(p_type is null or c.candidate_type=p_type)and(p_provider is null or s.provider_connection_id=p_provider)and(p_search is null or c.normalized_value ilike'%'||left(p_search,200)||'%')and(p_min_confidence is null or c.highest_confidence>=p_min_confidence)and(p_max_confidence is null or c.highest_confidence<=p_max_confidence)and(p_has_port is null or(c.network_port is not null)=p_has_port)and(p_project_id is null or exists(select 1 from public.ioc_candidate_acceptances a where a.owner_id=c.owner_id and a.candidate_id=c.id and a.project_id=p_project_id))and(p_cursor_at is null or(coalesce(c.last_seen_at,c.last_ingested_at),c.id)<(p_cursor_at,p_cursor_id))group by c.id order by coalesce(c.last_seen_at,c.last_ingested_at)desc,c.id desc limit least(greatest(p_limit,1),100)$$;

alter table public.ioc_provider_connections enable row level security;alter table public.ioc_ingestion_runs enable row level security;alter table public.ioc_candidates enable row level security;alter table public.ioc_candidate_sources enable row level security;alter table public.ioc_provider_cursors enable row level security;alter table public.ioc_candidate_acceptances enable row level security;
create policy ioc_connections_read on public.ioc_provider_connections for select to authenticated using(owner_id=auth.uid());create policy ioc_runs_read on public.ioc_ingestion_runs for select to authenticated using(owner_id=auth.uid());create policy ioc_candidates_read on public.ioc_candidates for select to authenticated using(owner_id=auth.uid());create policy ioc_sources_read on public.ioc_candidate_sources for select to authenticated using(owner_id=auth.uid());create policy ioc_cursors_read on public.ioc_provider_cursors for select to authenticated using(owner_id=auth.uid());create policy ioc_acceptances_read on public.ioc_candidate_acceptances for select to authenticated using(owner_id=auth.uid());
revoke all on function public.claim_ioc_connection(uuid,uuid,public.ioc_ingestion_trigger),public.complete_ioc_ingestion(uuid,uuid,uuid,uuid,public.ioc_ingestion_run_status,bigint,text,jsonb),public.fail_ioc_ingestion(uuid,uuid,uuid,uuid,text,text)from public,anon,authenticated;grant execute on function public.claim_ioc_connection(uuid,uuid,public.ioc_ingestion_trigger),public.complete_ioc_ingestion(uuid,uuid,uuid,uuid,public.ioc_ingestion_run_status,bigint,text,jsonb),public.fail_ioc_ingestion(uuid,uuid,uuid,uuid,text,text)to service_role;
revoke all on function public.triage_ioc_candidate(uuid,text),public.accept_ioc_candidate(uuid,uuid,text,public.cve_severity),public.list_ioc_inbox(public.ioc_candidate_status,public.ioc_candidate_type,uuid,text,integer,integer,boolean,uuid,timestamptz,uuid,integer)from public,anon;grant execute on function public.triage_ioc_candidate(uuid,text),public.accept_ioc_candidate(uuid,uuid,text,public.cve_severity),public.list_ioc_inbox(public.ioc_candidate_status,public.ioc_candidate_type,uuid,text,integer,integer,boolean,uuid,timestamptz,uuid,integer)to authenticated;
do $$begin if has_function_privilege('authenticated','public.complete_ioc_ingestion(uuid,uuid,uuid,uuid,public.ioc_ingestion_run_status,bigint,text,jsonb)','EXECUTE')then raise exception 'trusted IOC completion ACL broadened';end if;end$$;
commit;
